	.select({
		chatId: chatMessage.chatId,
		source: chatMessage.source,
		position: sql<number>`row_number() over (
			partition by ${chatMessage.chatId}
			order by ${chatMessage.createdAt} asc
		)`.as('position'),
	})
	.from(chatMessage)
	.where(and(eq(chatMessage.role, 'user'), isNull(chatMessage.supersededAt)))
	.as('user_messages');
const chatSource = sql`${userMessages.source}`;

