// A chat's source is defined by its first user message, not by each message: assistant
// messages carry no source, so filtering per message would leak answers from admin chats.
// Resolved once per chat in a derived relation rather than as a correlated subquery, so
// the part-grain query below reads chat_message once instead of once per message part.
const rankedUserMessages = qb
	.select({
		chatId: chatMessage.chatId,
		source: chatMessage.source,
		position: sql<number>`row_number() over (partition by ${chatMessage.chatId} order by ${chatMessage.createdAt} asc)`.as(
			'position',
		),
	})
	.from(chatMessage)
	.where(sql`${chatMessage.role} = 'user' and ${chatMessage.supersededAt} is null`)
	.as('ranked_user_messages');

const firstUserMessage = qb
	.select({ chatId: rankedUserMessages.chatId, source: rankedUserMessages.source })
	.from(rankedUserMessages)
	.where(sql`${rankedUserMessages.position} = 1`)
	.as('first_user_message');

const chatSource = sql`${firstUserMessage.source}`;

