import { Database } from 'bun:sqlite';

import { getScopedViews } from './src/db/app-db-views';

const OLD_BODY = `select "chat_message"."chat_id", "chat"."user_id", "user"."name" as "user_name", "chat"."title", "chat_message"."role", "message_part"."type", "message_part"."text", "chat_message"."stop_reason", "chat_message"."error_message", "chat_message"."llm_provider", "chat_message"."llm_model_id", "chat_message"."superseded_at" as "superseded_at", "chat_message"."source" as "message_source", (
		select source_message.source
		from "chat_message" as source_message
		where source_message.chat_id = "chat"."id"
			and source_message.role = 'user'
			and source_message.superseded_at is null
		order by source_message.created_at asc
		limit 1
	) as "chat_source", "message_part"."tool_name", "message_part"."tool_state", "message_part"."tool_error_text", "message_part"."tool_input", "message_part"."tool_output", "message_feedback"."vote", "message_feedback"."explanation", "message_part"."created_at" as "created_at" from "message_part" left join "message_feedback" on ("message_part"."message_id" = "message_feedback"."message_id" and "message_part"."order" = ((select min("order") from "message_part" "sibling_part" where "sibling_part"."message_id" = "message_part"."message_id"))) left join "chat_message" on "message_part"."message_id" = "chat_message"."id" left join "chat" on "chat"."id" = "chat_message"."chat_id" left join "user" on "user"."id" = "chat"."user_id" where ("chat"."project_id" in (select "project_id" from "_scope") and ((
		select source_message.source
		from "chat_message" as source_message
		where source_message.chat_id = "chat"."id"
			and source_message.role = 'user'
			and source_message.superseded_at is null
		order by source_message.created_at asc
		limit 1
	) is null or (
		select source_message.source
		from "chat_message" as source_message
		where source_message.chat_id = "chat"."id"
			and source_message.role = 'user'
			and source_message.superseded_at is null
		order by source_message.created_at asc
		limit 1
	) <> 'admin')) order by "chat_message"."chat_id", "message_part"."created_at" asc`;

const NEW_BODY = getScopedViews().find((view) => view.name === 'v_messages')!.body;

const conn = new Database(':memory:');
conn.run(`
	create table "user" (id text primary key, name text);
	create table chat (id text primary key, user_id text, title text, project_id text);
	create table chat_message (
		id text primary key, chat_id text, role text, stop_reason text, error_message text,
		llm_provider text, llm_model_id text, superseded_at integer, source text, created_at integer
	);
	create table message_part (
		id text primary key, message_id text, "order" integer, type text, text text,
		tool_name text, tool_state text, tool_error_text text, tool_input text, tool_output text,
		created_at integer
	);
	create table message_feedback (id text primary key, message_id text, vote text, explanation text);
	create index chat_message_chatId_idx on chat_message (chat_id);
	create index message_part_message_id_idx on message_part (message_id);
	create temp table _scope (project_id text not null);
	insert into _scope values ('p1');
	insert into "user" values ('u1', 'Ada');
`);

interface Fixture {
	chat: string;
	project: string;
	messages: { role: string; source: string | null; superseded: number | null; at: number }[];
}

const fixtures: Fixture[] = [
	{
		chat: 'web-chat',
		project: 'p1',
		messages: [
			{ role: 'user', source: 'web', superseded: null, at: 100 },
			{ role: 'assistant', source: null, superseded: null, at: 200 },
			{ role: 'user', source: 'admin', superseded: null, at: 300 },
		],
	},
	{
		chat: 'admin-chat',
		project: 'p1',
		messages: [
			{ role: 'user', source: 'admin', superseded: null, at: 100 },
			{ role: 'assistant', source: null, superseded: null, at: 200 },
		],
	},
	{
		chat: 'superseded-first',
		project: 'p1',
		messages: [
			{ role: 'user', source: 'admin', superseded: 50, at: 50 },
			{ role: 'user', source: 'slack', superseded: null, at: 150 },
		],
	},
	{
		chat: 'no-user-messages',
		project: 'p1',
		messages: [{ role: 'assistant', source: null, superseded: null, at: 100 }],
	},
	{
		chat: 'other-project',
		project: 'p2',
		messages: [{ role: 'user', source: 'web', superseded: null, at: 100 }],
	},
];

const insertChat = conn.query('insert into chat values (?, ?, ?, ?)');
const insertMessage = conn.query(
	'insert into chat_message values (?, ?, ?, null, null, null, null, ?, ?, ?)',
);
const insertPart = conn.query(
	'insert into message_part values (?, ?, ?, ?, ?, null, null, null, null, null, ?)',
);

for (const fixture of fixtures) {
	insertChat.run(fixture.chat, 'u1', `${fixture.chat} title`, fixture.project);
	fixture.messages.forEach((message, index) => {
		const messageId = `${fixture.chat}-m${index}`;
		insertMessage.run(messageId, fixture.chat, message.role, message.superseded, message.source, message.at);
		insertPart.run(`${messageId}-p0`, messageId, 0, 'text', `${messageId} part 0`, message.at);
		insertPart.run(`${messageId}-p1`, messageId, 1, 'text', `${messageId} part 1`, message.at + 1);
	});
}

conn.run(`create temp view v_old as ${OLD_BODY}`);
conn.run(`create temp view v_new as ${NEW_BODY}`);

const projection = 'chat_id, role, text, message_source, chat_source';
const old = conn.query(`select ${projection} from v_old`).all();
const fresh = conn.query(`select ${projection} from v_new`).all();

console.log('rows old / new:', old.length, fresh.length);
console.log('identical:', JSON.stringify(old) === JSON.stringify(fresh));
console.table(fresh);

for (const view of ['v_old', 'v_new']) {
	const plan = conn
		.query(`explain query plan select count(*) from ${view}`)
		.all() as { detail: string }[];
	console.log(`\n== ${view} ==`);
	console.log(plan.map((step) => step.detail).join('\n'));
}

conn.close();

